def _ensure_assets():
    adir = _os.path.join(_os.path.abspath(_os.path.dirname(__file__)), "assets")
    try:
        _os.makedirs(adir, exist_ok=True)
        b = _os.path.join(adir, "banner.jpg")
        q = _os.path.join(adir, "pay_qr.jpg")
        if not _os.path.exists(b):
            with open(b, "wb") as fh:
                fh.write(base64.b64decode(_BANNER_B64))
        if not _os.path.exists(q):
            with open(q, "wb") as fh:
                fh.write(base64.b64decode(_PAY_QR_B64))
        # the rentable GOJO x OMEGA engine goes NEXT TO this file:
        # _ensure_template() (in the main section below) copies it into
        # data/template/ and registers it as the rent template.
        t = _os.path.join(_os.path.abspath(_os.path.dirname(__file__)),
                          "template_bot.py")
        if not _os.path.exists(t):
            with open(t, "wb") as fh:
                fh.write(base64.b64decode(_TEMPLATE_B64))
    except Exception as _e:
        print("warning: could not write assets/template files:", _e)

_ensure_assets()
del _BANNER_B64, _PAY_QR_B64, _TEMPLATE_B64


# ---------------------------------------------------------------------------
# Dependency preflight - friendly message instead of a cryptic traceback
# ---------------------------------------------------------------------------
def _preflight():
    if _sys.version_info >= (3, 13):
        print("NOTE: you are on Python " + _sys.version.split()[0] +
              " - if pip installs fail below, install Python 3.12 from python.org.")
    need = [
        ("telegram", '"python-telegram-bot[job-queue]>=21.6"', True),
        ("psutil",   "psutil", True),
        ("qrcode",   '"qrcode[pil]"', True),
        ("httpx",    "httpx", True),
        ("flask",    "flask", False),   # optional: keep-alive/direct file server
        ("waitress", "waitress", False), # optional but recommended for VPS file serving
    ]
    missing, optional_missing = [], []
    for mod, pip_name, required in need:
        try:
            __import__(mod)
        except ImportError:
            (missing if required else optional_missing).append(pip_name)
    if missing:
        print()
        print("=" * 64)
        print("MISSING LIBRARIES - run this one line, then try again:")
        print()
        print("    python -m pip install " + " ".join(missing))
        print()
        print("If an install fails with a build error, install Python 3.12")
        print("from https://www.python.org/downloads/ and retry.")
        print("=" * 64)
        _sys.exit(1)
    if optional_missing:
        print("note: flask not installed - web keep-alive server will be skipped (bot still works).")

_preflight()





