# -*- coding: utf-8 -*-
"""Central configuration — everything is env-driven, no secrets in code."""
import os
import re
from decimal import Decimal

# ---------------------------------------------------------------------------
# .env auto-loader (no python-dotenv dependency needed).
# Windows-friendly: just put a .env file next to this file (or set real env
# vars in PowerShell / your host's dashboard — real env vars ALWAYS win).
# ---------------------------------------------------------------------------
BASE_DIR = os.path.abspath(os.path.dirname(__file__))

def _load_dotenv():
    path = os.path.join(BASE_DIR, ".env")
    if not os.path.isfile(path):
        return
    try:
        with open(path, encoding="utf-8-sig") as fh:   # utf-8-sig strips BOM
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, _, val = line.partition("=")
                key = key.strip()
                val = val.strip().strip('"').strip("'")
                if key and key not in os.environ:   # real env vars take priority
                    os.environ[key] = val
    except Exception as e:
        print("warning: could not read .env:", e)

_load_dotenv()

# ---------------------------------------------------------------------------
# EASY MODE: paste your values directly between the quotes if you don't want
# to bother with .env files or environment variables. Real env vars and a
# .env file always take priority over these fallbacks.
# ---------------------------------------------------------------------------
BOT_TOKEN_FALLBACK = ""   # e.g. "123456789:AAH..."
OWNER_ID_FALLBACK  = ""   # e.g. "111222333"
ADMIN_LOG_CHAT_FALLBACK = ""  # e.g. "-1001234567890"

def _env(key: str, fallback: str) -> str:
    """env var -> .env file -> hard-coded fallback above."""
    return os.environ.get(key) or fallback

BOT_TOKEN     = _env("BOT_TOKEN", BOT_TOKEN_FALLBACK)
OWNER_ID      = int(_env("OWNER_ID", OWNER_ID_FALLBACK) or 0)
ADMIN_LOG_CHAT = _env("ADMIN_LOG_CHAT", ADMIN_LOG_CHAT_FALLBACK)
ADMIN_IDS     = {int(x) for x in re.split(r"[,\s]+", os.environ.get("ADMIN_IDS", "")) if x.strip()}
UPDATE_CHANNEL = os.environ.get("UPDATE_CHANNEL", "")
PORT          = int(os.environ.get("PORT", "8080"))
# Public base URL for direct VPS file links. Examples:
#   http://YOUR_VPS_IP:8080
#   https://files.example.com
PUBLIC_BASE_URL = os.environ.get("PUBLIC_BASE_URL", "").rstrip("/")
FILE_LINK_SECRET = os.environ.get("FILE_LINK_SECRET", "")
REQUIRE_UPI_REF = os.environ.get("REQUIRE_UPI_REF", "1") == "1"

ALL_ADMIN_IDS = {OWNER_ID} | ADMIN_IDS

# ---- Business rules (all tweakable) ----
RS_PER_CREDIT          = Decimal("10")      # 1 credit = ₹10
TEMPLATE_DAILY_CREDITS = Decimal("2.5")     # run owner's template bot w/ user token
OWNFILE_DAILY_CREDITS  = Decimal("5")       # host your own uploaded file
MIN_CREDITS_START      = Decimal("1")       # minimum balance to start a deployment
CHARGE_INTERVAL_HOURS  = 24                 # deduction cadence while running
MAX_FILES_PER_USER     = 5                  # stored file slots per user
UPI_ID                 = os.environ.get("UPI_ID", "pahal28@fam")
UPI_NAME               = os.environ.get("UPI_NAME", "pahal mourya")
FREE_JOIN_CREDITS      = Decimal("5")       # welcome bonus for every new user

# ---- Paths ----
DATA_DIR   = os.path.join(BASE_DIR, "data")
FILES_DIR  = os.path.join(DATA_DIR, "user_files")
TEMPLATE_DIR = os.path.join(DATA_DIR, "template")
LOG_DIR    = os.path.join(DATA_DIR, "run_logs")
DB_PATH    = os.path.join(DATA_DIR, "platform.db")

# ---- Assets (banner + static payment QR shipped with the bot) ----
ASSETS_DIR   = os.path.join(BASE_DIR, "assets")
