# -*- coding: utf-8 -*-
"""Token validation via Bot API getMe — tokens are never logged in full."""
import httpx

def mask(token: str) -> str:
    if not token or ":" not in token:
        return "(none)"
    aid, secret = token.split(":", 1)
    return f"{aid}:{secret[:3]}…{secret[-2:]}" if len(secret) > 6 else f"{aid}:***"

def validate_bot_token(token: str):
    """Returns (ok, bot_username, error_message)."""
    token = token.strip()
    if not re_match(token):
        return False, "", "❌ That doesn't look like a bot token (format: 123456:ABC-...)."
    try:
        r = httpx.get(f"https://api.telegram.org/bot{token}/getMe", timeout=15)
        data = r.json()
        if data.get("ok") and data.get("result", {}).get("is_bot"):
            return True, "@" + data["result"].get("username", "unknown"), ""
        return False, "", "❌ Telegram rejected this token (revoked or wrong). Get a fresh one from @BotFather."
    except Exception as e:
        return False, "", f"❌ Could not reach Telegram: {type(e).__name__}"

def re_match(token: str) -> bool:
    import re
    return bool(re.fullmatch(r"\d{6,12}:[A-Za-z0-9_-]{20,}", token))


