# -*- coding: utf-8 -*-
"""SQLite persistence — users, wallets, payments, deployments, files, settings."""
import re
import sqlite3
import threading
from datetime import datetime
from decimal import Decimal



_local = threading.local()
_lock = threading.RLock()

def _conn() -> sqlite3.Connection:
    if not hasattr(_local, "conn") or _local.conn is None:
        _local.conn = sqlite3.connect(DB_PATH, check_same_thread=False, timeout=30)
        _local.conn.row_factory = sqlite3.Row
        _local.conn.execute("PRAGMA journal_mode=WAL")
        _local.conn.execute("PRAGMA busy_timeout=10000")
    return _local.conn

def init_db():
    with _lock:
        c = _conn()
        c.executescript("""
        CREATE TABLE IF NOT EXISTS users (
            user_id INTEGER PRIMARY KEY,
            username TEXT DEFAULT '',
            first_name TEXT DEFAULT '',
            joined_at TEXT
        );
        CREATE TABLE IF NOT EXISTS wallets (
            user_id INTEGER PRIMARY KEY,
            balance TEXT NOT NULL DEFAULT '0',
            total_purchased TEXT NOT NULL DEFAULT '0',
            total_spent TEXT NOT NULL DEFAULT '0'
        );
        CREATE TABLE IF NOT EXISTS payments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            credits TEXT NOT NULL,
            amount_rs TEXT NOT NULL,
            upi_ref TEXT DEFAULT '',
            proof_file_id TEXT DEFAULT '',
            status TEXT NOT NULL DEFAULT 'pending',   -- pending | approved | rejected
            created_at TEXT,
            decided_by INTEGER,
            decided_at TEXT,
            note TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS deployments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            kind TEXT NOT NULL,                      -- template | ownfile
            bot_token TEXT DEFAULT '',
            user_bot_username TEXT DEFAULT '',
            file_name TEXT DEFAULT '',
            stored_path TEXT DEFAULT '',
            daily_cost TEXT NOT NULL,
            started_at TEXT,
            last_charge TEXT,
            status TEXT NOT NULL DEFAULT 'running',  -- running | stopped
            stop_reason TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS files (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            file_name TEXT NOT NULL,
            stored_path TEXT NOT NULL,
            scan TEXT DEFAULT '',
            approved INTEGER DEFAULT 0,
            added_at TEXT
        );
        CREATE TABLE IF NOT EXISTS transactions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            delta TEXT NOT NULL,
            reason TEXT,
            created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS settings (
            key TEXT PRIMARY KEY,
            value TEXT
        );
        """)
        c.commit()

# ---------- users ----------
def upsert_user(uid: int, username: str = "", first_name: str = "") -> bool:
    """Register/refresh user. Returns True ONLY the very first time (for welcome bonus)."""
    with _lock:
        c = _conn()
        row = c.execute("SELECT user_id FROM users WHERE user_id=?", (uid,)).fetchone()
        is_new = row is None
        if is_new:
            c.execute("INSERT INTO users (user_id, username, first_name, joined_at) VALUES (?,?,?,?)",
                      (uid, username, first_name, datetime.utcnow().isoformat()))
        else:
            c.execute("UPDATE users SET username=?, first_name=? WHERE user_id=?",
                      (username, first_name, uid))
        c.execute("INSERT OR IGNORE INTO wallets (user_id) VALUES (?)", (uid,))
        c.commit()
        return is_new

def get_user(uid: int):
    with _lock:
        row = _conn().execute("SELECT * FROM users WHERE user_id=?", (uid,)).fetchone()
        return dict(row) if row else None

def all_user_ids():
    with _lock:
        return [r["user_id"] for r in _conn().execute("SELECT user_id FROM users").fetchall()]

# ---------- wallet ----------
def _fmt(d: Decimal) -> str:
    return str(d.quantize(Decimal("0.01")))

def get_balance(uid: int) -> Decimal:
    with _lock:
        row = _conn().execute("SELECT balance FROM wallets WHERE user_id=?", (uid,)).fetchone()
        return Decimal(row["balance"]) if row else Decimal("0")

def adjust_credits(uid: int, delta: Decimal, reason: str = ""):
    with _lock:
        c = _conn()
        c.execute("INSERT OR IGNORE INTO wallets (user_id) VALUES (?)", (uid,))
        c.execute("UPDATE wallets SET balance = CAST(CAST(balance AS REAL) + ? AS TEXT) WHERE user_id=?",
                  (float(delta), uid))
        if delta > 0:
            c.execute("UPDATE wallets SET total_purchased = CAST(CAST(total_purchased AS REAL) + ? AS TEXT) WHERE user_id=?",
                      (float(delta), uid))
        else:
            c.execute("UPDATE wallets SET total_spent = CAST(CAST(total_spent AS REAL) + ? AS TEXT) WHERE user_id=?",
                      (float(abs(delta)), uid))
        c.execute("INSERT INTO transactions (user_id, delta, reason, created_at) VALUES (?,?,?,?)",
                  (uid, _fmt(delta), reason, datetime.utcnow().isoformat()))
        c.commit()
        return get_balance(uid)

def wallet_summary(uid: int):
    with _lock:
        row = _conn().execute("SELECT * FROM wallets WHERE user_id=?", (uid,)).fetchone()
        return dict(row) if row else {"balance": "0", "total_purchased": "0", "total_spent": "0"}

# ---------- payments ----------
def create_payment(uid: int, credits: Decimal, amount_rs: Decimal, upi_ref: str, proof_file_id: str) -> int:
    with _lock:
        c = _conn()
        cur = c.execute(
            "INSERT INTO payments (user_id, credits, amount_rs, upi_ref, proof_file_id, status, created_at) "
            "VALUES (?,?,?,?,?, 'pending', ?)",
            (uid, _fmt(credits), _fmt(amount_rs), upi_ref, str(proof_file_id), datetime.utcnow().isoformat()))
        c.commit()
        return cur.lastrowid

def pending_payments():
    with _lock:
        return [dict(r) for r in _conn().execute(
            "SELECT * FROM payments WHERE status='pending' ORDER BY id").fetchall()]

def get_payment(pid: int):
    with _lock:
        row = _conn().execute("SELECT * FROM payments WHERE id=?", (pid,)).fetchone()
        return dict(row) if row else None

def decide_payment(pid: int, approve: bool, admin_id: int, note: str = ""):
    with _lock:
        c = _conn()
        c.execute("UPDATE payments SET status=?, decided_by=?, decided_at=?, note=? WHERE id=? AND status='pending'",
                  ("approved" if approve else "rejected", admin_id,
                   datetime.utcnow().isoformat(), note, pid))
        c.commit()

# ---------- deployments ----------
def add_deployment(uid: int, kind: str, daily_cost: Decimal, bot_token: str = "",
                   bot_username: str = "", file_name: str = "", stored_path: str = "") -> int:
    with _lock:
        c = _conn()
        cur = c.execute(
            "INSERT INTO deployments (user_id, kind, bot_token, user_bot_username, file_name, stored_path, "
            "daily_cost, started_at, last_charge, status) VALUES (?,?,?,?,?,?,?,?,?, 'running')",
            (uid, kind, bot_token, bot_username, file_name, stored_path,
             _fmt(daily_cost), datetime.utcnow().isoformat(), datetime.utcnow().isoformat()))
        c.commit()
        return cur.lastrowid

def set_deployment_status(did: int, status: str, reason: str = ""):
    with _lock:
        c = _conn()
        c.execute("UPDATE deployments SET status=?, stop_reason=? WHERE id=?", (status, reason, did))
        c.commit()

def touch_last_charge(did: int):
    with _lock:
        c = _conn()
        c.execute("UPDATE deployments SET last_charge=? WHERE id=?", (datetime.utcnow().isoformat(), did))
        c.commit()

def user_deployments(uid: int, running_only: bool = False):
    q = "SELECT * FROM deployments WHERE user_id=?"
    if running_only:
        q += " AND status='running'"
    q += " ORDER BY id DESC"
    with _lock:
        return [dict(r) for r in _conn().execute(q, (uid,)).fetchall()]

def get_deployment(did: int):
    with _lock:
        row = _conn().execute("SELECT * FROM deployments WHERE id=?", (did,)).fetchone()
        return dict(row) if row else None

def all_running_deployments():
    with _lock:
        return [dict(r) for r in _conn().execute(
            "SELECT * FROM deployments WHERE status='running' ORDER BY id").fetchall()]

def deployment_stats():
    with _lock:
        c = _conn()
        users = c.execute("SELECT COUNT(*) n FROM users").fetchone()["n"]
        running = c.execute("SELECT COUNT(*) n FROM deployments WHERE status='running'").fetchone()["n"]
        pending = c.execute("SELECT COUNT(*) n FROM payments WHERE status='pending'").fetchone()["n"]
        return users, running, pending

# ---------- files ----------
def add_file(uid: int, file_name: str, stored_path: str, scan: str = "", approved: bool = False) -> int:
    with _lock:
        c = _conn()
        cur = c.execute("INSERT INTO files (user_id, file_name, stored_path, scan, approved, added_at) VALUES (?,?,?,?,?,?)",
                        (uid, file_name, stored_path, scan, 1 if approved else 0, datetime.utcnow().isoformat()))
        c.commit()
        return cur.lastrowid

def user_files(uid: int):
    with _lock:
        return [dict(r) for r in _conn().execute(
            "SELECT * FROM files WHERE user_id=? ORDER BY id DESC", (uid,)).fetchall()]

def get_file_by_id(fid: int):
    with _lock:
        row = _conn().execute("SELECT * FROM files WHERE id=?", (int(fid),)).fetchone()
        return dict(row) if row else None

def file_count(uid: int) -> int:
    with _lock:
        row = _conn().execute("SELECT COUNT(*) n FROM files WHERE user_id=?", (uid,)).fetchone()
        return row["n"]

def file_row(uid: int, file_name: str):
    with _lock:
        row = _conn().execute("SELECT * FROM files WHERE user_id=? AND file_name=?", (uid, file_name)).fetchone()
        return dict(row) if row else None

def set_file_approval(fid: int, approved: bool, scan: str = None):
    with _lock:
        c = _conn()
        if scan is not None:
            c.execute("UPDATE files SET approved=?, scan=? WHERE id=?", (1 if approved else 0, scan, fid))
        else:
            c.execute("UPDATE files SET approved=? WHERE id=?", (1 if approved else 0, fid))
        c.commit()

def delete_file(uid: int, file_name: str):
    with _lock:
        c = _conn()
        c.execute("DELETE FROM files WHERE user_id=? AND file_name=?", (uid, file_name))
        c.commit()

# ---------- settings ----------
def get_setting(key: str, default=None):
    with _lock:
        row = _conn().execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
        return row["value"] if row else default

def set_setting(key: str, value):
    with _lock:
        c = _conn()
        c.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?,?)", (key, str(value)))
        c.commit()

# ---------- staff (admins & co-owners, db-stored) ----------
def _id_list(key: str) -> set:
    raw = get_setting(key, "") or ""
    return {int(x) for x in re.split(r"[,\s]+", raw) if x.strip()}

def _id_add(key: str, uid: int) -> bool:
    ids = _id_list(key)
    if uid in ids:
        return False
    ids.add(uid)
    set_setting(key, ",".join(str(i) for i in sorted(ids)))
    return True

def _id_remove(key: str, uid: int) -> bool:
    ids = _id_list(key)
    if uid not in ids:
        return False
    ids.discard(uid)
    set_setting(key, ",".join(str(i) for i in sorted(ids)))
    return True

def get_admin_ids() -> set:      return _id_list("admins")
def add_admin(uid: int) -> bool: return _id_add("admins", uid)
def remove_admin(uid: int) -> bool: return _id_remove("admins", uid)

def get_coowner_ids() -> set:        return _id_list("coowners")
def add_coowner(uid: int) -> bool:   return _id_add("coowners", uid)
def remove_coowner(uid: int) -> bool: return _id_remove("coowners", uid)


