# -*- coding: utf-8 -*-
"""
Payments — UPI QR generation + pricing + the daily billing job.

Flow: /buy → choose credits pack → bot generates UPI QR with exact amount
and a unique payment reference → user pays → /paid + screenshot + UPI ref →
admin panel approve/reject → credits credited.
"""
import qrcode
import qrcode.constants
import io
import os
import secrets
from decimal import Decimal
from datetime import datetime




def pack_credits(rs: Decimal) -> Decimal:
    return (rs / RS_PER_CREDIT).quantize(Decimal("0.01"))

def upi_link(amount: Decimal, ref: str) -> str:
    # tr = transaction reference so owner's UPI app groups the payment
    return (f"upi://pay?pa={UPI_ID}&pn={UPI_NAME}"
            f"&am={amount}&cu=INR&tn=CREDITS%20{ref}")

def make_qr(amount: Decimal, ref: str):
    """Returns (PIL Image, upi_link)."""
    qr = qrcode.QRCode(version=None, error_correction=qrcode.constants.ERROR_CORRECT_M,
                       box_size=10, border=4)
    qr.add_data(upi_link(amount, ref))
    qr.make(fit=True)
    return qr.make_image(fill_color="black", back_color="white")

def qr_bytes(amount: Decimal, ref: str) -> bytes:
    img = make_qr(amount, ref)
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return buf.getvalue()

def new_ref() -> str:
    return "BH" + secrets.token_hex(3).upper()  # e.g. BH4F2A91

def packs():
    """Credit packs the /buy menu offers (₹ value -> credits)."""
    return [
        (Decimal("50"),  "⚡ Starter  — ₹50"),
        (Decimal("100"), "🔥 Value    — ₹100"),
        (Decimal("250"), "💎 Pro      — ₹250"),
        (Decimal("500"), "👑 Ultra    — ₹500"),
    ]

# ---------- daily billing ----------
def daily_cost(kind: str) -> Decimal:
    return TEMPLATE_DAILY_CREDITS if kind == "template" else OWNFILE_DAILY_CREDITS

def next_charge_iso(now=None) -> str:
    return (now or datetime.utcnow()).isoformat()


# ========================================================================
# SECTION: process_manager
# ========================================================================

# -*- coding: utf-8 -*-
"""
Process manager — starts, stops and supervises user deployments.

Each deployment runs as its own subprocess with:
  - a MINIMAL, whitelisted environment (it NEVER inherits this platform's
    own BOT_TOKEN / OWNER_ID — the child is a different bot!)
  - HOST_TOKEN / BOT_HOST_TOKEN / BOT_TOKEN = the deployment's own token
    (renter's token for templates, optional /runtoken for own files)
  - OWNER_ID = the renter's Telegram id (the renter IS the owner of his
    rented instance — full powers inside it)
  - its OWN work directory (template files are copied into
    template/dep_<id>/ so renters' data files never collide)
  - per-deployment log file
  - LIVENESS CHECK: a script that dies within the first seconds is a
    FAILED start (bad token, crash, missing lib) — reported honestly
    with its logs instead of silently pretending to run
  - crash auto-restart after that (max 5 attempts, then stopped)
  - free-memory guard before starting anything
"""
import os
import shutil
import subprocess
import sys
import threading
import time
from datetime import datetime, timedelta

import psutil




_procs = {}          # deployment_id -> subprocess.Popen
_stop_flags = {}     # deployment_id -> True when user/admin requested stop
_monitors = {}       # deployment_id -> threading.Thread
_pm_lock = threading.RLock()

MAX_RESTARTS = 5
MIN_FREE_MB = 150
VERIFY_SECONDS = 3.0     # a child must survive this long to count as started

# Windows needs a few system vars or imports/subprocesses break.
_WIN_KEYS = ("SYSTEMROOT", "COMSPEC", "PATHEXT", "TEMP", "TMP",
             "USERPROFILE", "APPDATA", "LOCALAPPDATA", "PROGRAMFILES",
             "PROGRAMDATA", "WINDIR", "PROCESSOR_ARCHITECTURE")


def free_mem_ok() -> bool:
    return psutil.virtual_memory().available > MIN_FREE_MB * 1024 * 1024


def _child_env(token: str, owner_uid: int) -> dict:
    """Minimal, sanitized env for a child deployment.

    CRITICAL FIX: the old version did os.environ.copy() — the child then
    INHERITED this platform's own BOT_TOKEN, so a hosted/rented bot was
    actually the HOSTING bot (conflict, instant death, 'not live').
    Now the child gets exactly its own token + its own owner id.
    """
    env = {
        "PATH": os.environ.get(
            "PATH", "/usr/local/bin:/usr/bin:/bin:/usr/local/sbin"),
        "PYTHONUNBUFFERED": "1",
        "LANG": os.environ.get("LANG", "C.UTF-8"),
        "LC_ALL": os.environ.get("LC_ALL", "C.UTF-8"),
    }
    if "TZ" in os.environ:
        env["TZ"] = os.environ["TZ"]
    home = os.environ.get("HOME")
    if home:
        env["HOME"] = home            # pip cache etc.
    if os.name == "nt":
        for k in _WIN_KEYS:
            if k in os.environ:
                env[k] = os.environ[k]
    if token:
        # the deployment's own token — all common env names, so any
        # template/own-file that reads one of them finds ITS token
        env["HOST_TOKEN"] = token
        env["BOT_HOST_TOKEN"] = token
        env["BOT_TOKEN"] = token
    if owner_uid:
        # the renter becomes the OWNER of his rented instance
        env["OWNER_ID"] = str(owner_uid)
    # marker: templates can detect they are rented via BOT HOST
    env["BOT_HOST_PLATFORM"] = "1"
    return env


def _log_path(did: int) -> str:
    return os.path.join(LOG_DIR, f"dep_{did}.log")


def _write_log(did: int, line: str):
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(_log_path(did), "a", encoding="utf-8") as f:
            f.write(f"[{ts}] {line}\n")
    except OSError:
        pass


def tail_log(did: int, lines: int = 25) -> str:
    try:
        with open(_log_path(did), "r", encoding="utf-8", errors="replace") as f:
            return "".join(f.readlines()[-lines:])
    except FileNotFoundError:
        return "(no logs yet)"


def is_running(did: int) -> bool:
    with _pm_lock:
        p = _procs.get(did)
        return p is not None and p.poll() is None


def running_ids():
    with _pm_lock:
        return list(_procs.keys())


def _isolated_workdir(did: int, script_path: str, workdir: str) -> str:
    """Template deployments get their OWN copy in template/dep_<id>/.

    Rentable templates (e.g. the GOJO x OMEGA engine) write their data
    files (sudo_users.json, settings.json, ...) into the CURRENT WORKING
    DIRECTORY — if every renter shared one folder they would corrupt
    each other's state. Own files already run from per-user folders.
    """
    try:
        if os.path.abspath(workdir) != os.path.abspath(TEMPLATE_DIR):
            return workdir
        wd = os.path.join(TEMPLATE_DIR, f"dep_{did}")
        os.makedirs(wd, exist_ok=True)
        dst = os.path.join(wd, os.path.basename(script_path))
        if not os.path.isfile(dst):
            shutil.copyfile(script_path, dst)
        return wd
    except OSError:
        return workdir


def _spawn(did: int, script_path: str, token: str, workdir: str, owner_uid: int = 0):
    env = _child_env(token, owner_uid)
    _write_log(did, f"=== spawn {os.path.basename(script_path)} "
                    f"(token: {'yes' if token else 'none'}, owner_id: {owner_uid or '-'}) ===")
    logf = open(_log_path(did), "a", encoding="utf-8")
    try:
        return subprocess.Popen(
            [sys.executable, "-u", os.path.basename(script_path)],
            cwd=workdir,
            env=env,
            stdout=logf,
            stderr=subprocess.STDOUT,
        )
    finally:
        logf.close()          # child keeps its own inherited handle


def start(did: int, script_path: str, token: str, workdir: str,
          owner_uid: int = 0) -> bool:
    """Spawn a deployment and VERIFY it actually stays alive.

    Returns True only when the child survived the first VERIFY_SECONDS.
    A child that dies instantly (bad token, missing library, crash)
    returns False — the caller can then show the child's logs.
    NOTE: blocks up to ~VERIFY_SECONDS; from async code call it via
    asyncio.to_thread(pm.start, ...) so replies stay instant.
    """
    script_name = os.path.basename(script_path)
    if not os.path.isfile(os.path.join(workdir, script_name)):
        _write_log(did, f"ERROR: script not found: {script_path}")
        return False
    if not free_mem_ok():
        _write_log(did, "ERROR: host low on memory, refusing to start")
        return False
    workdir = _isolated_workdir(did, script_path, workdir)
    with _pm_lock:
        if is_running(did):
            return True
        _stop_flags.pop(did, None)
        p = _procs[did] = _spawn(did, script_path, token, workdir, owner_uid)
    # ── LIVENESS CHECK ─────────────────────────────────────────────
    try:
        p.wait(timeout=VERIFY_SECONDS)
        _write_log(did, f"died right after start (rc={p.returncode}) — NOT running")
        with _pm_lock:
            _procs.pop(did, None)
        return False
    except subprocess.TimeoutExpired:
        pass               # still alive after the verify window — good
    t = threading.Thread(target=_monitor,
                         args=(did, script_path, token, workdir, owner_uid),
                         daemon=True)
    with _pm_lock:
        _monitors[did] = t
    t.start()
    return True


def stop(did: int, reason: str = "manual stop") -> bool:
    """Kill a deployment (and its whole subprocess tree).

    NOTE: may block several seconds (graceful terminate -> kill).
    From async code call via asyncio.to_thread(pm.stop, ...) — otherwise
    every user's reply freezes while we wait for the child to die.
    """
    with _pm_lock:
        _stop_flags[did] = True
        p = _procs.get(did)
    if p and p.poll() is None:
        try:
            parent = psutil.Process(p.pid)
            kids = parent.children(recursive=True)
            for k in kids:
                k.terminate()
            parent.terminate()
            _gone, alive = psutil.wait_procs(kids + [parent], timeout=6)
            for proc in alive:
                proc.kill()
        except psutil.NoSuchProcess:
            pass
        try:
            p.wait(timeout=4)
        except subprocess.TimeoutExpired:
            p.kill()
    _write_log(did, f"=== stopped: {reason} ===")
    with _pm_lock:
        _procs.pop(did, None)
        _monitors.pop(did, None)
        _stop_flags.pop(did, None)
    return True


def _monitor(did: int, script_path: str, token: str, workdir: str,
             owner_uid: int = 0):
    restarts = 0
    while True:
        with _pm_lock:
            p = _procs.get(did)
        if p is None:
            return
        rc = p.wait()
        with _pm_lock:
            if _stop_flags.get(did):
                return  # clean user-requested stop
        restarts += 1
        if restarts > MAX_RESTARTS:
            _write_log(did, f"crashed (rc={rc}) — restart limit reached, giving up")
            db.set_deployment_status(did, "stopped", f"crash loop (rc={rc})")
            with _pm_lock:
                _procs.pop(did, None)
            return
        _write_log(did, f"crashed (rc={rc}) — auto-restart {restarts}/{MAX_RESTARTS} in 5s")
        time.sleep(5)
        if not free_mem_ok():
            _write_log(did, "low memory — delaying restart 60s")
            time.sleep(60)
        with _pm_lock:
            if _stop_flags.get(did) or did not in _procs:
                return
            _procs[did] = _spawn(did, script_path, token, workdir, owner_uid)


def stop_all(reason="shutdown"):
    with _pm_lock:
        ids = list(_procs.keys())
    for did in ids:
        stop(did, reason)
    return ids


def deploy_paths(deployment: dict):
    """Resolve (script_path, workdir) for a deployment row."""
    if deployment["kind"] == "template":
        return db.get_setting("template_script", "template_bot.py"), TEMPLATE_DIR
    return deployment["stored_path"], os.path.dirname(deployment["stored_path"])


def restart_all_from_db():
    """After a host reboot, resume every deployment marked running in DB."""
    resumed = []
    for d in db.all_running_deployments():
        script, workdir = deploy_paths(d)
        token = d["bot_token"]
        if d["kind"] == "template":
            token = db.get_setting("template_runtime_token", "") or token
        if start(d["id"], script, token, workdir, owner_uid=d["user_id"]):
            resumed.append(d["id"])
        else:
            db.set_deployment_status(d["id"], "stopped", "failed to resume after reboot")
    return resumed


def kill_by_owner(uid: int, reason: str) -> int:
    """Stop every running deployment of a user (used when balance hits zero)."""
    n = 0
    for d in db.user_deployments(uid, running_only=True):
        if stop(d["id"], reason):
            db.set_deployment_status(d["id"], "stopped", reason)
            n += 1
    return n


