# -*- coding: utf-8 -*-
"""Admin-channel logging + owner DM review copies. Tokens are always masked."""
import logging
from telegram.constants import ParseMode




logger = logging.getLogger("notify")

def _mask_token(d: dict):
    d = dict(d)
    if d.get("bot_token"):
        d["bot_token"] = mask(d["bot_token"])
    return d

def deployment_line(d: dict) -> str:
    if not d:
        return "(no deployment)"
    d = _mask_token(d)
    kind = "🤖 template" if d.get("kind") == "template" else "📦 own file"
    return (f"#{d.get('id','?')} {kind} — @{d.get('user_bot_username') or d.get('file_name','?')} "
            f"cost {d.get('daily_cost','?')}/day — status: {d.get('status','?')}")

def user_line(u: dict) -> str:
    if not u:
        return "(unknown user)"
    uname = f"@{u['username']}" if u.get("username") else "(no username)"
    return f"{u['user_id']} {uname} {u.get('first_name','')}"

async def admin_log(application, text: str, no_key=False):
    """Post an event line to the private admin channel (if configured)."""
    if not ADMIN_LOG_CHAT:
        return
    try:
        await application.bot.send_message(ADMIN_LOG_CHAT, text, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.warning("admin_log failed: %s", e)

async def owner_dm(application, text: str):
    if not OWNER_ID:
        return
    try:
        await application.bot.send_message(OWNER_ID, text, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.warning("owner_dm failed: %s", e)

# ---- event formatters ----
def ev_new_user(u: dict) -> str:
    return f"🆕 <b>New user</b>\n{user_line(u)}\nvia {u.get('joined_at','')[:19]}"

def ev_bot_started(d: dict, u: dict) -> str:
    d = _mask_token(d)
    return ("▶️ <b>Deployment started</b>\n"
            f"user: {user_line(u)}\n"
            f"deployment: {deployment_line(d)}")

def ev_bot_stopped(d: dict, reason: str) -> str:
    return (f"⏹ <b>Deployment stopped</b>\n{deployment_line(d)}\nreason: {reason}")

def ev_payment_requested(p: dict, u: dict) -> str:
    return ("💳 <b>Payment submitted</b>\n"
            f"payment #{p['id']} by {user_line(u)}\n"
            f"amount: ₹{p['amount_rs']} for {p['credits']} credits\n"
            f"UPI ref: {p['upi_ref'] or '(none)'}")

def ev_payment_decided(p: dict, u: dict, approved: bool, admin_id) -> str:
    emoji = "✅" if approved else "❌"
    return (f"{emoji} <b>Payment {'approved' if approved else 'rejected'}</b>\n"
            f"payment #{p['id']} by {user_line(u)}\n"
            f"amount: ₹{p['amount_rs']} for {p['credits']} credits\n"
            f"decided by admin {admin_id}")

def ev_file_hosted(d: dict, u: dict, scan_verdict: str) -> str:
    d = _mask_token(d)
    return ("📦 <b>File hosted</b>\n"
            f"user: {user_line(u)}\n"
            f"deployment: {deployment_line(d)}\n"
            f"scan: {scan_verdict}")

def ev_credits_topup(uid: int, credits: str, balance: str) -> str:
    return (f"➕ <b>Credits added</b>\n"
            f"user {uid}: +{credits} credits → balance {balance}")


