# -*- coding: utf-8 -*-
"""
CREDIT-BASED BOT HOSTING PLATFORM
════════════════════════════════
Monetized hosting service on python-telegram-bot v21+ (async).

Pricing (all configurable in config.py):
  • 1 credit = ₹10 (bought via UPI QR + admin approval)
  • Run OWNER'S TEMPLATE bot with your own token .... 2.5 credits/day
  • Host YOUR OWN file ................................ 5 credits/day

Users are free to host ANY file (no restrictions, no scanning).
Every event is logged to the private admin channel; hosted files are
sent to the owner's DM for records. Tokens are always masked in logs.

Env: BOT_TOKEN, OWNER_ID, ADMIN_IDS, ADMIN_LOG_CHAT, UPI_ID, UPI_NAME,
     UPDATE_CHANNEL, REQUIRE_UPI_REF, PORT, PUBLIC_BASE_URL
"""
import asyncio
import logging
import os
import io
import html
import secrets
import hashlib
import hmac
import shutil
import threading
from decimal import Decimal
from datetime import datetime, timedelta

from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup, BotCommand, InputMediaPhoto
from telegram.ext import (Application, ApplicationHandlerStop, CallbackQueryHandler,
                          CommandHandler, ContextTypes, MessageHandler,
                          TypeHandler, filters)
from telegram.constants import ParseMode








logging.basicConfig(level=logging.INFO,
                    format="%(asctime)s | %(levelname)s | %(name)s | %(message)s")
log = logging.getLogger("platform")

# state for multi-step conversations (kept in bot_data so restarts wipe them)
def _ukey(uid):
    return f"flow_{uid}"

def start_flow(context, uid, flow, **kw):
    context.bot_data[_ukey(uid)] = {"flow": flow, **kw}

def get_flow(context, uid):
    return context.bot_data.get(_ukey(uid))

def clear_flow(context, uid):
    context.bot_data.pop(_ukey(uid), None)

def _deployment_runtime_stats(did: int):
    try:
        with pm._pm_lock:
            proc = pm._procs.get(int(did))
        if not proc or proc.poll() is not None:
            return None
        ps = psutil.Process(proc.pid)
        with ps.oneshot():
            rss = ps.memory_info().rss
            cpu = ps.cpu_percent(interval=0.0)
            create = ps.create_time()
        uptime = max(0, int(datetime.now().timestamp() - create))
        if uptime < 60: up = f"{uptime}s"
        elif uptime < 3600: up = f"{uptime//60}m"
        elif uptime < 86400: up = f"{uptime//3600}h {(uptime%3600)//60}m"
        else: up = f"{uptime//86400}d {(uptime%86400)//3600}h"
        return {"cpu": cpu, "ram_mb": rss/(1024*1024), "uptime": up, "pid": ps.pid}
    except Exception:
        return None

async def _send_support_to_admins(context, user_id: int, text: str):
    u = db.get_user(user_id) or {}
    uname = f"@{u.get('username')}" if u.get('username') else "(no username)"
    msg = (f"📨 <b>User support message</b>\n\n"
           f"👤 {u.get('first_name','')} {uname}\n"
           f"🆔 <code>{user_id}</code>\n\n{html.escape(text)}")
    recipients = {C.OWNER_ID} if C.OWNER_ID else set()
    try:
        recipients.update(db.get_admin_ids())
        recipients.update(db.get_coowner_ids())
    except Exception:
        pass
    kb = InlineKeyboardMarkup([[InlineKeyboardButton("↩️ Reply", callback_data=f"support_{user_id}")]])
    for target in recipients:
        if not target: continue
        try:
            await context.bot.send_message(target, msg, parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception as e:
            log.warning("support delivery failed for %s: %s", target, e)

def fire(coro):
    """Run a coroutine in the background - replies stay instant even when
    admin logging / owner DMs are slow."""
    try:
        return asyncio.create_task(coro)
    except Exception:
        try:
            coro.close()
        except Exception:
            pass
        return None

# ─────────────────────────────────────────────────────────────────────────────
# ACCESS CONTROL
# ─────────────────────────────────────────────────────────────────────────────
async def guard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Gate every handler: register user, welcome bonus, lock check.

    guard() runs FIRST (group -2) on every update, so it is the SOLE
    registrar: on a user's very first interaction it grants the
    FREE_JOIN_CREDITS welcome bonus right here and leaves a 'was_new'
    flag for cmd_start to greet them with the bonus line.
    """
    u = update.effective_user
    if not u:
        return
    if not u.is_bot:
        is_new = db.upsert_user(u.id, u.username or "", u.first_name or "")
        if is_new:
            db.adjust_credits(u.id, C.FREE_JOIN_CREDITS, "welcome bonus")
            context.user_data["was_new"] = True
            try:
                fire(N.admin_log(context.application, N.ev_new_user(db.get_user(u.id))))
            except Exception:
                pass
    if db.get_setting("platform_locked", "0") == "1" and not is_admin(u.id):
        if update.effective_message:
            await send_reply(update, context, "\U0001F512 Platform is temporarily locked. Try again later.")
        raise ApplicationHandlerStop

def is_admin(uid: int) -> bool:
    """Admins: env-set admins + db-stored admins + co-owners + owner."""
    if uid == C.OWNER_ID or uid in C.ADMIN_IDS:
        return True
    try:
        return uid in db.get_admin_ids() or uid in db.get_coowner_ids()
    except Exception:
        return False

def is_owner(uid: int) -> bool:
    return uid == C.OWNER_ID

def is_coowner(uid: int) -> bool:
    return uid == C.OWNER_ID or (uid in db.get_coowner_ids())

# ─────────────────────────────────────────────────────────────────────────────
# BANNER — every command response ships with the GOJO X MUZAN banner image
# ─────────────────────────────────────────────────────────────────────────────
def _safe_cut(text: str, limit: int) -> str:
    """Cut text at limit without slicing an HTML tag in half."""
    if len(text) <= limit:
        return text
    cut = text[:limit]
    lt, gt = cut.rfind("<"), cut.rfind(">")
    if lt > gt:            # a tag was cut open -> retreat to before it
        cut = cut[:lt]
    return cut.rstrip()

def _chunks(text: str, limit: int = 4000):
    """Split long text into telegram-sized pieces (tag-safe)."""
    out = []
    while text:
        piece = _safe_cut(text, limit)
        out.append(piece)
        text = text[len(piece):].lstrip()
    return out

async def _text_fallback(msg, text: str, kb=None):
    """Plain-text fallback when the banner cannot be sent."""
    try:
        parts = _chunks(text, 4096) or [""]
        for i, part in enumerate(parts):
            await msg.reply_text(part, parse_mode=ParseMode.HTML,
                                 reply_markup=kb if i == 0 else None)
    except Exception:
        pass

_BANNER_CACHE = {"file_id": None}
_QR_CACHE = {"file_id": None}     # owner's UPI QR - upload once, then file_id

def _photo_input(photo):
    """Normalize a photo argument for Bot API calls.
    Accepts: file path (str) | raw bytes | file_id/URL (str) | open handle.
    Paths are opened; bytes are wrapped in BytesIO."""
    if isinstance(photo, str):
        if os.path.isfile(photo):
            return open(photo, "rb")
        return photo                       # already a file_id or URL
    if isinstance(photo, (bytes, bytearray)):
        return io.BytesIO(bytes(photo))
    return photo                           # already a handle

async def send_reply(update, context, text: str, kb=None, photo=None):
    """Standard response renderer.

    COMMAND mode -> banner photo + caption (+ buttons); long texts
                    continue as follow-up messages.
    BUTTON mode  -> the message the user has OPEN is edited in place
                    (caption / text / media swap). The whole menu
                    conversation stays inside ONE message - buttons
                    never open a new chat line.
    """
    msg = update.effective_message
    q = getattr(update, "callback_query", None)
    chat_id = msg.chat_id if msg else None
    if chat_id is None:
        return
    # \u2500\u2500 BUTTON MODE: continue in the SAME message \u2500\u2500
    if q is not None:
        if photo is not None:
            try:
                media = InputMediaPhoto(_photo_input(photo),
                                        caption=_safe_cut(text, 1024),
                                        parse_mode=ParseMode.HTML)
                await q.edit_message_media(media=media, reply_markup=kb)
                return
            except Exception as e:
                if "not modified" in str(e).lower():
                    return
                log.warning("media swap failed: %s", e)
        await edit_menu(q, text, kb)
        return
    # \u2500\u2500 COMMAND MODE: banner + caption (+ buttons) \u2500\u2500
    cap = _safe_cut(text, 1024)
    rest = text[len(cap):].strip()
    try:
        if photo is not None:
            # e.g. the owner's payment QR - it replaces the banner itself.
            # Static QR -> reuse the cached file_id (no 64KB re-upload).
            if photo == C.PAY_QR_PATH and _QR_CACHE["file_id"]:
                use = _QR_CACHE["file_id"]
            else:
                use = _photo_input(photo)
            m = await context.bot.send_photo(chat_id, use,
                                             caption=cap or None,
                                             parse_mode=ParseMode.HTML, reply_markup=kb)
            if photo == C.PAY_QR_PATH and m is not None and getattr(m, "photo", None):
                _QR_CACHE["file_id"] = m.photo[-1].file_id
        else:
            f = _BANNER_CACHE["file_id"]
            if f is None:
                if not os.path.isfile(C.BANNER_PATH):
                    _BANNER_CACHE["file_id"] = False
                    raise FileNotFoundError
                with open(C.BANNER_PATH, "rb") as fh:
                    m = await context.bot.send_photo(chat_id, fh, caption=cap or None,
                                                     parse_mode=ParseMode.HTML,
                                                     reply_markup=kb)
                    _BANNER_CACHE["file_id"] = m.photo[-1].file_id
            elif f is False:
                raise FileNotFoundError
            else:
                await context.bot.send_photo(chat_id, f, caption=cap or None,
                                             parse_mode=ParseMode.HTML, reply_markup=kb)
        for part in _chunks(rest, 4000):
            try:
                await context.bot.send_message(chat_id, part, parse_mode=ParseMode.HTML)
            except Exception:
                pass
    except FileNotFoundError:
        await _text_fallback(msg, text, kb)
    except Exception as e:
        log.warning("banner send failed: %s", e)
        await _text_fallback(msg, text, kb)

async def edit_menu(q, text: str, kb=None):
    """Edit a menu message - banner photos get their caption edited,
    plain text messages get their text edited. Long texts continue
    as follow-up messages so nothing is lost."""
    try:
        if q.message and q.message.photo:
            cap = _safe_cut(text, 1024)
            await q.edit_message_caption(caption=cap, parse_mode=ParseMode.HTML,
                                         reply_markup=kb)
            rest = text[len(cap):].strip()
            for part in _chunks(rest, 4000):
                try:
                    await q.message.reply_text(part, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
            return
        await q.edit_message_text(_safe_cut(text, 4096), parse_mode=ParseMode.HTML,
                                  reply_markup=kb)
    except Exception as e:
        if "not modified" in str(e).lower():
            return
        await _text_fallback(q.message, text, kb)

