async def _handle_proof(update, context, uid, photo_file_id):
    msg = update.effective_message
    pid = db.create_payment(uid, Decimal("0"), Decimal("0"), "", photo_file_id)
    p = db.get_payment(pid)
    u = db.get_user(uid)
    uname = ("@" + u["username"]) if u and u.get("username") else ""
    caption = (
        "💳 <b>— PAYMENT RECEIVED —</b>\n\n"
        f"👤 <b>User:</b> <a href=\"tg://user?id={uid}\">{(u or {}).get('first_name') or uid}</a> {uname}\n"
        f"🆔 <b>ID:</b> <code>{uid}</code>\n"
        f"💰 <b>Balance now:</b> {db.get_balance(uid)} cr\n"
        f"📁 <b>Proof:</b> #{pid}\n\n"
        f"✅ <b>To credit:</b> <code>/addcredits {uid} &lt;amount&gt;</code>\n"
        f"❌ <b>To reject:</b> <code>/rejectpayment {pid}</code>"
    )
    # DM to owner + every co-owner (they can also /addcredits)
    targets = {C.OWNER_ID} | set(db.get_coowner_ids())
    for t in targets:
        if not t:
            continue
        try:
            await context.bot.send_photo(t, photo_file_id, caption=caption, parse_mode=ParseMode.HTML)
        except Exception as e:
            log.warning("payment dm to %s failed: %s", t, e)
    fire(N.admin_log(context.application, N.ev_payment_requested(p, u)))
    clear_flow(context, uid)
    await send_reply(update, context, "✅ Screenshot forwarded to the owner.\n"
        "You'll get credits once he verifies — usually fast. /balance to check.",
        kb=wallet_kb())

async def cmd_paid_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Screenshot arrives as a photo message while awaiting proof."""
    uid = update.effective_user.id
    flow = get_flow(context, uid)
    if not flow or flow.get("flow") != "awaiting_proof":
        return
    await _handle_proof(update, context, uid, update.effective_message.photo[-1].file_id)

async def cmd_addcredits(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """OWNER: /addcredits <user_id> <credits> — credit a user after verifying his screenshot."""
    if not is_owner(update.effective_user.id) and not is_admin(update.effective_user.id):
        return
    if len(context.args) < 2:
        return await send_reply(update, context, "Usage: /addcredits <user_id> <credits>")
    try:
        target = int(context.args[0])
        credits = Decimal(context.args[1])
    except Exception:
        return await send_reply(update, context, "Usage: /addcredits <user_id> <credits>")
    if credits <= 0 or credits > 10000:
        return await send_reply(update, context, "Credits must be between 0 and 10000.")
    bal = db.adjust_credits(target, credits, f"manual topup by {update.effective_user.id}")
    u = db.get_user(target)
    if not u:
        return await send_reply(update, context, f"Unknown user {target} — he must /start the bot first.")
    await N.admin_log(context.application, N.ev_credits_topup(target, str(credits), str(bal)))
    try:
        await context.bot.send_message(target,
            f"✅ Owner added <b>{credits} credits</b> to your account!\n"
            f"New balance: <b>{bal}</b> credits 🎉", parse_mode=ParseMode.HTML)
    except Exception:
        pass
    await send_reply(update, context, f"✅ Credited {credits} → user {target} (now {bal} cr)",
        kb=admin_back_kb())

async def cmd_rejectpayment(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """OWNER: /rejectpayment <payment_id> — reject a submitted proof."""
    if not (is_owner(update.effective_user.id) or is_admin(update.effective_user.id)):
        return
    if not context.args:
        return await send_reply(update, context, "Usage: /rejectpayment <payment_id>")
    try:
        pid = int(context.args[0])
    except Exception:
        return await send_reply(update, context, "Usage: /rejectpayment <payment_id>")
    p = db.get_payment(pid)
    if not p:
        return await send_reply(update, context, f"Payment #{pid} not found.")
    if p["status"] != "pending":
        return await send_reply(update, context, f"Payment #{pid} is already {p['status']}.")
    u = db.get_user(p["user_id"])
    db.decide_payment(pid, False, update.effective_user.id, "owner rejected")
    await N.admin_log(context.application, N.ev_payment_decided(p, u, False, update.effective_user.id))
    try:
        await context.bot.send_message(p["user_id"],
            f"❌ Your payment proof #{pid} was rejected by the owner.\n"
            "If you believe this is a mistake, contact him directly.")
    except Exception:
        pass
    await send_reply(update, context, f"❌ Payment #{pid} rejected.", kb=admin_back_kb())

# ---- ADMIN: payment decisions ----
async def cb_pending_pays(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not is_admin(q.from_user.id):
        return await q.answer("Admins only", show_alert=True)
    await q.answer()
    pend = db.pending_payments()
    if not pend:
        return await edit_menu(q, "✅ No pending payments.", kb=admin_panel_kb())
    for p in pend[:10]:
        u = db.get_user(p["user_id"])
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("✅ Approve", callback_data=f"pay_{p['id']}_ok"),
             InlineKeyboardButton("❌ Reject", callback_data=f"pay_{p['id']}_no")]
        ])
        text = (f"💳 <b>Payment #{p['id']}</b>\n"
                f"user: {N.user_line(u)}\n"
                f"₹{p['amount_rs']} → {p['credits']} credits\n"
                f"UPI ref: {p['upi_ref'] or '(none)'}\n"
                f"submitted: {p['created_at'][:19]}")
        proof = p.get("proof_file_id")
        try:
            if proof:
                await context.bot.send_photo(q.from_user.id, proof, caption=text,
                                             parse_mode=ParseMode.HTML, reply_markup=kb)
            else:
                await context.bot.send_message(q.from_user.id, text, parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception as e:
            log.warning("send pending payment failed: %s", e)
    await edit_menu(q, f"🚦 Sent {min(len(pend),10)} pending payments to your DM.", kb=admin_panel_kb())

async def cb_pay_decide(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not is_admin(q.from_user.id):
        return await q.answer("Admins only", show_alert=True)
    await q.answer()
    _, pid, action = q.data.split("_")
    pid = int(pid)
    approve = action == "ok"
    p = db.get_payment(pid)
    if not p or p["status"] != "pending":
        try:
            return await q.edit_message_reply_markup(reply_markup=None)
        except Exception:
            return
    u = db.get_user(p["user_id"])
    db.decide_payment(pid, approve, q.from_user.id)
    if approve:
        amount = Decimal(str(p["credits"] or 0))
        if amount > 0:
            db.adjust_credits(p["user_id"], amount, f"payment #{pid}")
            verdict = (f"\u2705 Approved +{amount} cr to {N.user_line(u)}\n"
                       f"New balance: {db.get_balance(p['user_id'])}")
        else:
            # screenshot flow: no amount attached yet
            verdict = (f"\u2705 Payment #{pid} marked approved.\n"
                       f"\U0001F4B3 Now credit the amount: <code>/addcredits {p['user_id']} &lt;credits&gt;</code>")
    else:
        verdict = f"\u274C Rejected payment #{pid}"
    # the proof may be a photo (caption) or plain text
    try:
        if q.message and q.message.photo:
            await q.edit_message_caption(verdict, parse_mode=ParseMode.HTML)
        else:
            await q.edit_message_text(verdict, parse_mode=ParseMode.HTML)
    except Exception:
        pass
    await N.admin_log(context.application, N.ev_payment_decided(p, u, approve, q.from_user.id))
    try:
        if approve and Decimal(str(p["credits"] or 0)) > 0:
            await context.bot.send_message(p["user_id"],
                f"\u2705 Payment approved! +{p['credits']} credits.\n"
                f"New balance: {db.get_balance(p['user_id'])}",
                parse_mode=ParseMode.HTML)
        elif approve:
            await context.bot.send_message(p["user_id"],
                "\u2705 Payment proof accepted \u2014 owner will add your credits shortly.")
        else:
            await context.bot.send_message(p["user_id"],
                f"\u274C Payment #{pid} was rejected. Contact the owner if you believe this is a mistake.")
    except Exception:
        pass


