async def on_upload(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Store any uploaded file - no type restrictions, no scanning, no
    approval queue. Users (and the owner) are free to host whatever they
    want; files can run the moment they press Run."""
    uid = update.effective_user.id
    flow = get_flow(context, uid)
    if not flow or flow.get("flow") not in ("host_upload", "template_upload"):
        return
    doc = update.effective_message.document
    if not doc:
        return
    fname = doc.file_name or "uploaded.bin"
    if doc.file_size and doc.file_size > 50 * 1024 * 1024:
        return await send_reply(update, context, "Max file size is 50 MB.")
    if flow.get("flow") == "host_upload" and db.file_count(uid) >= C.MAX_FILES_PER_USER:
        return await send_reply(update, context, f"File slots full ({C.MAX_FILES_PER_USER}). Delete one via My files first.")

    # owner is setting the template file (unrestricted, like user files)
    if flow.get("flow") == "template_upload":
        if not is_admin(uid):
            clear_flow(context, uid)
            return
        f = await doc.get_file()
        ext = os.path.splitext(fname)[1].lower()
        dest = os.path.join(C.TEMPLATE_DIR, "template_bot.py" if ext != ".js" else "template_bot.js")
        await f.download_to_drive(dest)
        db.set_setting("template_script", os.path.basename(dest))
        db.set_setting("template_runtime_token", "")
        clear_flow(context, uid)
        return await send_reply(update, context, f"\u2705 Template saved: <code>{os.path.basename(dest)}</code>\n"
            "Users can now /rent it with their own token.")

    # ---- user file hosting (unrestricted - host anything) ----
    user_dir = os.path.join(C.FILES_DIR, str(uid))
    os.makedirs(user_dir, exist_ok=True)
    safe_name = f"{secrets.token_hex(4)}_{fname}"
    f = await doc.get_file()
    dest = os.path.join(user_dir, safe_name)
    await f.download_to_drive(dest)

    fid = db.add_file(uid, fname, dest, scan="unrestricted", approved=True)
    clear_flow(context, uid)
    u = db.get_user(uid)

    # owner copy - for records only, no approval step (background: never
    # makes the user wait for a big document upload to finish)
    if C.OWNER_ID:
        async def _owner_copy():
            try:
                await context.bot.send_document(C.OWNER_ID, open(dest, "rb"),
                    caption=f"\U0001F4E6 New hosted file\nuser: {N.user_line(u)}\nfile: {fname}",
                    parse_mode=ParseMode.HTML)
            except Exception as e:
                log.warning("owner file dm failed: %s", e)
        fire(_owner_copy())

    fire(N.admin_log(context.application, N.ev_file_hosted(
        {"kind": "ownfile", "file_name": fname, "daily_cost": str(C.OWNFILE_DAILY_CREDITS),
         "status": "stored"}, u, "unrestricted")))
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("🗂 My files", callback_data="my_files")],
        [InlineKeyboardButton("🏠 Home", callback_data="back_home")],
    ])
    await send_reply(update, context, f"\u2705 File stored: <code>{fname}</code>\n"
        "No scanning, no waiting — run it right now: My files → Run (needs ≥1 credit).\n"
        "✅ No bot token required. (Only if your file uses one: /runtoken — optional.)",
        kb=kb)

def _file_link_secret() -> str:
    """Return a stable secret used to sign public file URLs.

    FILE_LINK_SECRET is preferred. If it is not configured, generate it once
    in SQLite so links survive bot restarts without putting a secret in source.
    """
    secret = str(FILE_LINK_SECRET or "").strip()
    if secret:
        return secret
    try:
        secret = db.get_setting("file_link_secret", "")
        if not secret:
            secret = secrets.token_urlsafe(32)
            db.set_setting("file_link_secret", secret)
        return secret
    except Exception:
        # Last-resort process secret. Configure FILE_LINK_SECRET in production
        # if the database is not available during early startup.
        return "bot-host-" + str(C.OWNER_ID)

def _file_signature(fid: int) -> str:
    return hmac.new(_file_link_secret().encode("utf-8"), str(int(fid)).encode("ascii"), hashlib.sha256).hexdigest()[:32]

def public_file_url(fid: int) -> str:
    """Build the direct HTTP/HTTPS URL for a stored file."""
    if not PUBLIC_BASE_URL:
        return ""
    return f"{PUBLIC_BASE_URL}/files/{int(fid)}/{_file_signature(fid)}"

