async def cb_file_run(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    uid = q.from_user.id
    fid = int(q.data.split("_")[1])
    f = next((x for x in db.user_files(uid) if x["id"] == fid), None)
    if not f:
        return await q.answer("File not found", show_alert=True)
    if db.get_balance(uid) < C.MIN_CREDITS_START:
        return await q.answer(f"Need ≥{C.MIN_CREDITS_START} credits — /buy", show_alert=True)
    existing = [d for d in db.user_deployments(uid, running_only=True)
                if d["kind"] == "ownfile" and d["file_name"] == f["file_name"]]
    if existing:
        return await q.answer("This file is already running", show_alert=True)
    token = db.get_setting(f"runtoken_{uid}", "")   # optional - most files need none
    did = db.add_deployment(uid, "ownfile", C.OWNFILE_DAILY_CREDITS,
                            file_name=f["file_name"], stored_path=f["stored_path"],
                            bot_token=token, bot_username="")
    started = await asyncio.to_thread(pm.start, did, f["stored_path"], token,
                                       os.path.dirname(f["stored_path"]), uid)
    if started:
        db.adjust_credits(uid, -C.OWNFILE_DAILY_CREDITS, f"day-1 host #{did}")
        db.touch_last_charge(did)
        d = db.get_deployment(did)
        u = db.get_user(uid)
        fire(N.admin_log(context.application, N.ev_bot_started(d, u)))
        await edit_menu(q, f"▶️ <b>RUNNING</b> — {f['file_name']} (deployment #{did})\n"
            f"Charged {C.OWNFILE_DAILY_CREDITS} credits for day 1. Balance: {db.get_balance(uid)}\n\n"
            "Give it a few seconds to boot, then check 📄 Logs below\n"
            "to watch it come alive.",
            kb=deployment_kb(did))
    else:
        db.set_deployment_status(did, "stopped", "failed to start")
        logs = (pm.tail_log(did, 12) or "(no output)")[:900]
        await edit_menu(q, f"❌ <b>Failed to start</b> — {f['file_name']}\n"
            f"<pre>{logs}</pre>\n"
            "Common causes: missing libraries, syntax error, or the file\n"
            "exited immediately. Fix it and Run again.",
            kb=InlineKeyboardMarkup([
                [InlineKeyboardButton("📄 Logs", callback_data=f"dep_{did}_logs")],
                [InlineKeyboardButton("🗃 My files", callback_data="my_files")],
                [InlineKeyboardButton("🏠 Home", callback_data="back_home")],
            ]))

