async def cb_dep_view(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Open one deployment's controls inside the open message."""
    q = update.callback_query
    await q.answer()
    try:
        did = int(q.data.split("_")[1])
    except Exception:
        return
    d = db.get_deployment(did)
    if not d or (d["user_id"] != q.from_user.id and not is_admin(q.from_user.id)):
        return await q.answer("Not found", show_alert=True)
    running = d["status"] == "running" and pm.is_running(did)
    status = "🟢 running" if running else "🔴 stopped"
    emoji = "🛢" if d["kind"] == "template" else "📦"
    name = f"@{d['user_bot_username']}" if d["user_bot_username"] else (d["file_name"] or "-")
    stats = _deployment_runtime_stats(did) if running else None
    live = (f"\n🧠 CPU: {stats['cpu']:.1f}% · 💾 RAM: {stats['ram_mb']:.1f} MB · ⏱ {stats['uptime']}" if stats else "")
    text = (f"{emoji} <b>Deployment #{d['id']}</b>\n"
            f"bot / file: {name}\n"
            f"cost: {d['daily_cost']} credits/day · {status}\n"
            f"started: {(d['started_at'] or '')[:19]}{live}\n\n"
            "⏹ stop · 🔄 restart · 📄 logs · 📊 stats")
    await edit_menu(q, text, kb=deployment_kb(did))

async def cb_dep_control(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    parts = q.data.split("_")            # dep_<id>_<action>
    did, action = int(parts[1]), parts[2]
    d = db.get_deployment(did)
    if not d or d["user_id"] != q.from_user.id and not is_admin(q.from_user.id):
        return await q.answer("Not yours", show_alert=True)
    if action == "stop":
        await asyncio.to_thread(pm.stop, did, "user stop")
        db.set_deployment_status(did, "stopped", "user stop")
        fire(N.admin_log(context.application, N.ev_bot_stopped(d, "user stop")))
        return await edit_menu(q, f"⏹ Deployment #{did} stopped.", kb=deployment_kb(did))
    if action == "restart":
        if db.get_balance(d["user_id"]) < C.MIN_CREDITS_START:
            return await q.answer(f"Need ≥{C.MIN_CREDITS_START} credits", show_alert=True)
        script, workdir = pm.deploy_paths(d)
        token = d["bot_token"] or db.get_setting(f"runtoken_{d['user_id']}", "")
        ok = await asyncio.to_thread(pm.start, did, script, token, workdir, d["user_id"])
        if ok:
            db.set_deployment_status(did, "running", "restarted")
            return await edit_menu(q, f"🔄 Deployment #{did} restarted.", kb=deployment_kb(did))
        logs = (pm.tail_log(did, 10) or "(no output)")[:600]
        return await edit_menu(q, f"❌ Restart failed:\n<pre>{logs}</pre>", kb=deployment_kb(did))
    if action == "logs":
        return await edit_menu(q, f"📄 <b>Logs #{did}</b>\n<pre>{pm.tail_log(did, 20)[:3500]}</pre>",
                               kb=deployment_kb(did))

    if action == "stats":
        stats = _deployment_runtime_stats(did)
        if not stats:
            return await edit_menu(q, f"🔴 <b>Deployment #{did}</b> is not running.", kb=deployment_kb(did))
        return await edit_menu(q,
            f"📊 <b>Live stats — Deployment #{did}</b>\n\n"
            f"🟢 Status: running\n⚙️ PID: <code>{stats['pid']}</code>\n"
            f"🧠 CPU: <b>{stats['cpu']:.1f}%</b>\n💾 RAM: <b>{stats['ram_mb']:.1f} MB</b>\n"
            f"⏱ Uptime: <b>{stats['uptime']}</b>", kb=deployment_kb(did))

