async def cmd_botmsg(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """ADMIN ONLY: send an inline message directly to every registered user.

    Usage: !botmsg your message here
    This is intentionally a one-line command so the admin can send a message
    immediately without entering a separate broadcast flow.
    """
    uid = update.effective_user.id
    if not is_admin(uid):
        return

    raw = (update.effective_message.text or "").strip()
    # Remove the !botmsg prefix only; everything after it is the message.
    msg_text = raw[len("!botmsg"):].strip() if raw.lower().startswith("!botmsg") else ""
    if not msg_text:
        return await send_reply(
            update, context,
            "Usage: <code>!botmsg Your message here</code>",
            kb=admin_back_kb()
        )

    total, sent, failed = 0, 0, 0
    for target in db.all_user_ids():
        total += 1
        try:
            await context.bot.send_message(chat_id=target, text=msg_text, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("💬 Reply to owner", callback_data="support_reply")]]))
            sent += 1
        except Exception as e:
            failed += 1
            log.warning("!botmsg failed for %s: %s", target, e)
        # Keep a safe gap between messages for Telegram flood protection.
        await asyncio.sleep(0.05)

    await send_reply(
        update, context,
        f"📨 <b>Bot message sent.</b>\n\nSent: <b>{sent}</b>/<b>{total}</b>\nFailed: <b>{failed}</b>",
        kb=admin_back_kb()
    )

async def cmd_broadcast(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    flow = get_flow(context, uid)
    if not flow or flow.get("flow") != "broadcast":
        return
    if not is_admin(uid):
        clear_flow(context, uid)
        return
    total, sent, failed = 0, 0, 0
    msg = update.effective_message
    for target in db.all_user_ids():
        total += 1
        try:
            await msg.copy(chat_id=target)
            sent += 1
        except Exception:
            failed += 1
        await asyncio.sleep(0.05)  # ~20 msg/s global limit safety
    clear_flow(context, uid)
    await send_reply(update, context, f"📢 Broadcast done — sent {sent}/{total} (failed {failed}).")

async def cmd_cancel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    clear_flow(context, update.effective_user.id)
    await send_reply(update, context, "Cancelled.", kb=main_menu(update.effective_user.id))

# ─────────────────────────────────────────────────────────────────────────────
# ------------------------------------------------------------
# STAFF MANAGEMENT (co-owner role)
#   /addadmin <id|@user>    co-owner+   promote to admin
#   /removeadmin <id|@user> co-owner+   demote admin
#   /addcoowner <id>        OWNER ONLY  promote to co-owner
#   /removecoowner <id>     OWNER ONLY  demote co-owner
#   /staff                  admin+      list the whole team
# ------------------------------------------------------------
def _resolve_target(context, arg: str):
    """Accept numeric id or @username -> (uid, user_row) or (None, None)."""
    arg = (arg or "").strip().lstrip("@")
    if not arg:
        return None, None
    if arg.isdigit():
        uid = int(arg)
        return uid, db.get_user(uid)
    # username lookup
    for uid_ in db.all_user_ids():
        row = db.get_user(uid_)
        if row and (row.get("username") or "").lower() == arg.lower():
            return row["user_id"], row
    return None, None

def _staff_line(uid: int) -> str:
    u = db.get_user(uid)
    tag = ("@" + u["username"]) if u and u.get("username") else (str(uid))
    name = (u or {}).get("first_name") or ""
    return f"<a href=\"tg://user?id={uid}\">{name or uid}</a> {tag} <code>{uid}</code>"

async def cmd_addadmin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """CO-OWNER+: /addadmin <id or @user>"""
    uid = update.effective_user.id
    if not is_coowner(uid):
        return await send_reply(update, context, "\U0001F6AB Co-owners only.")
    if not context.args:
        return await send_reply(update, context, "Usage: <code>/addadmin &lt;user_id or @username&gt;</code>")
    target, row = _resolve_target(context, context.args[0])
    if not target:
        return await send_reply(update, context,
            "\u26a0\ufe0f User not found. He must /start the bot first "
            "(then you can use his @username or numeric id).")
    if target == C.OWNER_ID:
        return await send_reply(update, context, "\U0001F914 The owner needs no promotion.")
    if db.add_admin(target):
        await N.admin_log(context.application,
            f"\U0001F6E0 Admin added: {_staff_line(target)}\nby: {_staff_line(uid)}")
        try:
            await context.bot.send_message(target,
                "\U0001F6E0 You are now an <b>admin</b>! /panel for your tools.",
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return await send_reply(update, context,
            f"\u2705 <b>Admin added</b>\n{_staff_line(target)}")
    return await send_reply(update, context, "He's already an admin (or env-set admin).")

async def cmd_removeadmin(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """CO-OWNER+: /removeadmin <id or @user>"""
    uid = update.effective_user.id
    if not is_coowner(uid):
        return await send_reply(update, context, "\U0001F6AB Co-owners only.")
    if not context.args:
        return await send_reply(update, context, "Usage: <code>/removeadmin &lt;user_id or @username&gt;</code>")
    target, row = _resolve_target(context, context.args[0])
    if not target:
        return await send_reply(update, context, "\u26a0\ufe0f User not found (no /start yet).")
    if target == C.OWNER_ID:
        return await send_reply(update, context, "\U0001F6AB Can't touch the owner.")
    if target in db.get_coowner_ids():
        return await send_reply(update, context,
            "\U0001F451 That's a <b>co-owner</b> \u2014 remove co-owner instead (owner only).")
    if target in C.ADMIN_IDS:
        return await send_reply(update, context,
            "\u26a0\ufe0f That admin is env-set (ADMIN_IDS in .env). "
            "Remove him from the .env to demote him.")
    if db.remove_admin(target):
        await N.admin_log(context.application,
            f"\U0001F6E0 Admin removed: {_staff_line(target)}\nby: {_staff_line(uid)}")
        try:
            await context.bot.send_message(target,
                "\U0001F6E0 You are no longer an admin.",
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return await send_reply(update, context,
            f"\u2705 <b>Admin removed</b>\n{_staff_line(target)}")
    return await send_reply(update, context, "He's not a db-stored admin.")

