# CALLBACK ROUTER (menus)
# ─────────────────────────────────────────────────────────────────────────────
async def cb_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    data = q.data or ""
    uid = q.from_user.id
    if data == "back_home":
        await q.answer()
        return await render_home(q, context, uid)
    if data == "noop":
        return await q.answer()
    if data == "paid_now":
        await q.answer()
        start_flow(context, uid, "awaiting_proof")
        return await edit_menu(q, "\U0001F4F8 <b>Send your payment screenshot</b> as a photo now.\n"
            "It goes straight to the owner \u2014 credits land once he verifies.",
            kb=InlineKeyboardMarkup([
                [InlineKeyboardButton("\U0001F4B3 Buy menu", callback_data="buy_menu")],
                [InlineKeyboardButton("\U0001F3E0 Home", callback_data="back_home")],
            ]))
    if data == "wallet":
        await q.answer()
        w = db.wallet_summary(uid)
        return await edit_menu(q, f"💰 <b>Wallet</b>\n\nBalance: <b>{w['balance']}</b> credits\n"
            f"Bought total: {w['total_purchased']} · Spent: {w['total_spent']}", kb=wallet_kb())
    if data == "buy_menu":
        await q.answer()
        return await cmd_buy(update, context)
    if data.startswith("buy_"):
        return await cb_buy_select(update, context)
    if data == "rent_template":
        await q.answer()
        return await cmd_rent(update, context)
    if data == "upload_prompt":
        await q.answer()
        return await cmd_host(update, context)
    if data == "my_files":
        await q.answer()
        return await cmd_myfiles(update, context)
    if data == "my_bots":
        await q.answer()
        return await cmd_mybots(update, context)
    if data.startswith("file_") and data.endswith("_view"):
        return await cb_file_view(update, context)
    if data.startswith("file_") and data.endswith("_run"):
        return await cb_file_run(update, context)
    if data.startswith("file_") and data.endswith("_del"):
        fid = int(data.split("_")[1])
        f = next((x for x in db.user_files(uid) if x["id"] == fid), None)
        if f:
            # don't delete while running
            running = [d for d in db.user_deployments(uid, running_only=True)
                       if d["file_name"] == f["file_name"]]
            if running:
                return await q.answer("Stop it first (My deployments)", show_alert=True)
            try: os.remove(f["stored_path"])
            except OSError: pass
            db.delete_file(uid, f["file_name"])
        await q.answer("Deleted")
        return await cmd_myfiles(update, context)
    if data.startswith("dep_") and data.endswith("_view"):
        return await cb_dep_view(update, context)
    if data.startswith("dep_"):
        return await cb_dep_control(update, context)
    if data == "support_reply":
        await q.answer()
        start_flow(context, uid, "support_reply")
        return await edit_menu(q, "💬 <b>Reply to the owner/staff</b>\n\nSend your message now.", kb=home_kb())
    if data.startswith("support_"):
        if not is_admin(uid):
            return await q.answer("Admins only", show_alert=True)
        try: target_uid = int(data.split("_", 1)[1])
        except Exception: return await q.answer("Invalid user", show_alert=True)
        if not db.get_user(target_uid): return await q.answer("User not found", show_alert=True)
        await q.answer()
        start_flow(context, uid, "support_to_user", target_uid=target_uid)
        return await edit_menu(q, f"↩️ <b>Replying to user <code>{target_uid}</code></b>\n\nSend your message now.", kb=admin_back_kb())
    if data == "admin_panel":
        return await cb_admin_panel(update, context)
    if data == "pending_pays":
        return await cb_pending_pays(update, context)
    if data == "all_users":
        return await cb_all_users(update, context)
    if data == "all_deployments":
        return await cb_all_deployments(update, context)
    if data == "lock_toggle":
        return await cb_lock_toggle(update, context)
    if data == "template_upload_prompt":
        return await cb_template_prompt(update, context)
    if data == "broadcast_prompt":
        await q.answer()
        return await cmd_broadcast(update, context)
    await q.answer()

# ─────────────────────────────────────────────────────────────────────────────
# DAILY BILLING JOB — charges every running deployment every 24h
# ─────────────────────────────────────────────────────────────────────────────
async def billing_job(context: ContextTypes.DEFAULT_TYPE):
    log.info("billing job tick")
    charged, stopped, warned = [], [], []
    for d in db.all_running_deployments():
        try:
            last = datetime.fromisoformat(d["last_charge"])
        except Exception:
            db.touch_last_charge(d["id"])
            continue
        uid, did = d["user_id"], d["id"]
        cost = Decimal(d["daily_cost"])
        bal = db.get_balance(uid)
        # LOW-BALANCE WARNING (once per 24h per user, while balance < 2x cost)
        try:
            wkey = f"warned_{uid}"
            if bal < cost * 2 and db.get_setting(wkey, "0") == "0":
                db.set_setting(wkey, "1")
                warned.append(uid)
                await context.bot.send_message(uid,
                    "⚠️ <b>Credits running low!</b>\n"
                    f"Balance: <b>{bal}</b> credits \u2014 deployment #{did} costs {cost}/day.\n"
                    f"At zero the bot <b>stops automatically</b>. Top up now: /buy",
                    parse_mode=ParseMode.HTML)
        except Exception:
            pass
        if datetime.utcnow() - last < timedelta(hours=C.CHARGE_INTERVAL_HOURS):
            continue
        if bal >= cost:
            db.adjust_credits(uid, -cost, f"daily charge dep #{did}")
            db.touch_last_charge(did)
            charged.append((did, uid, str(cost)))
        else:
            if db.get_setting(f"warned_{uid}", "0") == "1" and bal >= cost * 3:
                db.set_setting(f"warned_{uid}", "0")
            await asyncio.to_thread(pm.stop, did, "insufficient credits")
            db.set_deployment_status(did, "stopped", "insufficient credits")
            stopped.append((did, uid))
            try:
                await context.bot.send_message(uid,
                    f"⏹ Deployment #{did} stopped — balance hit zero.\n"
                    "Top up with /buy and restart it from /mybots.")
            except Exception:
                pass
    if charged or stopped:
        lines = [f"💸 <b>Daily billing</b> — {len(charged)} charged, {len(stopped)} stopped"]
        for did, uid, c in charged[:15]:
            lines.append(f"#{did} user {uid}: -{c} cr")
        for did, uid in stopped[:15]:
            lines.append(f"#{did} user {uid}: STOPPED (no credits)")
        await N.admin_log(context.application, "\n".join(lines))

# ─────────────────────────────────────────────────────────────────────────────
# TEXT ROUTER — multi-step flows
# ─────────────────────────────────────────────────────────────────────────────
async def text_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    text = (update.effective_message.text or "").strip()

    # Admin-only instant broadcast command: !botmsg <message>
    # Handle it here because python-telegram-bot CommandHandler only handles /commands.
    if text.lower().startswith("!botmsg") and (len(text) == 7 or text[7].isspace()):
        return await cmd_botmsg(update, context)

    flow = get_flow(context, uid)
    if not flow:
        return
    f = flow.get("flow")
    if f == "rent_token":
        return await _rent_token(update, context)
    if f == "runtoken":
        return await _runtoken_reply(update, context)
    if f == "support_reply":
        clear_flow(context, uid)
        msg = (update.effective_message.text or "").strip()
        if msg:
            await _send_support_to_admins(context, uid, msg)
            return await send_reply(update, context, "✅ <b>Message sent.</b> The owner/staff will reply.", kb=home_kb())
        return
    if f == "support_to_user":
        if not is_admin(uid):
            clear_flow(context, uid); return
        target_uid = int(flow.get("target_uid", 0))
        clear_flow(context, uid)
        msg = (update.effective_message.text or "").strip()
        if not msg or not target_uid: return
        try:
            await context.bot.send_message(target_uid, f"👑 <b>Owner/Staff reply</b>\n\n{html.escape(msg)}", parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("💬 Reply", callback_data="support_reply")]]))
            return await send_reply(update, context, "✅ Reply delivered.", kb=admin_back_kb())
        except Exception as e:
            log.warning("support reply failed: %s", e)
            return await send_reply(update, context, "❌ Could not deliver the reply.", kb=admin_back_kb())
    # unknown text in other flows: ignore

async def photo_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    flow = get_flow(context, uid)
    if not flow:
        return
    if flow.get("flow") == "awaiting_proof":
        return await cmd_paid_photo(update, context)

