def _ensure_template():
    """Make sure a rentable template exists — the GOJO x OMEGA engine ships
    with the bot (template_bot.py next to this file / embedded in the
    single-file edition). Users can rent it immediately, no setup needed."""
    try:
        cur = db.get_setting("template_script", "")
        if cur in ("", "sample_template.py"):   # "" = fresh; legacy = swap
            src = os.path.join(C.BASE_DIR, "template_bot.py")
            if os.path.isfile(src):
                os.makedirs(C.TEMPLATE_DIR, exist_ok=True)
                dst = os.path.join(C.TEMPLATE_DIR, "template_bot.py")
                if not os.path.isfile(dst):
                    shutil.copyfile(src, dst)
                db.set_setting("template_script", "template_bot.py")
                log.info("rentable template installed: template_bot.py")
    except Exception as e:
        log.warning("template bootstrap failed: %s", e)

def run_flask_keepalive():
    try:
        from flask import Flask, abort, send_file
    except ImportError:
        log.info("flask not installed - keep-alive/direct file server skipped")
        return
    app = Flask("keepalive")

    @app.route("/")
    def home():
        return "🛡 BOT HOST platform is alive"

    @app.route("/files/<int:fid>/<signature>", methods=["GET", "HEAD"])
    def direct_file(fid: int, signature: str):
        """Serve a stored file directly from the VPS, bypassing Telegram.

        Signed URLs prevent arbitrary database file IDs from being guessed.
        Flask/Werkzeug handles conditional requests and byte ranges through
        send_file(), which makes large downloads resumable in normal clients.
        """
        expected = _file_signature(fid)
        if not hmac.compare_digest(str(signature), expected):
            abort(404)
        try:
            row = db.get_file_by_id(fid)
        except Exception:
            row = None
        if not row:
            abort(404)
        path = row.get("stored_path", "")
        if not path or not os.path.isfile(path):
            abort(404)
        try:
            response = send_file(
                path,
                as_attachment=True,
                download_name=row.get("file_name") or os.path.basename(path),
                conditional=True,
                etag=True,
                max_age=3600,
            )
            response.headers["Cache-Control"] = "public, max-age=3600"
            response.headers["Accept-Ranges"] = "bytes"
            response.headers["X-Content-Type-Options"] = "nosniff"
            return response
        except (OSError, ValueError):
            abort(404)

    def _run():
        port = int(os.environ.get("PORT", C.PORT))
        try:
            try:
                from waitress import serve
                # Waitress is substantially better suited than Flask's dev
                # server for concurrent VPS downloads.
                serve(app, host="0.0.0.0", port=port, threads=8, connection_limit=1000)
            except ImportError:
                log.warning("waitress not installed - using Flask development server; install waitress for faster direct file serving")
                app.run(host="0.0.0.0", port=port, threaded=True)
        except OSError as e:
            log.warning("keep-alive/direct file port %s unavailable (%s) - web server skipped", port, e)

    t = threading.Thread(target=_run, daemon=True)
    t.start()
    if PUBLIC_BASE_URL:
        log.info("direct VPS file hosting enabled: %s/files/<id>/<signature>", PUBLIC_BASE_URL)
    else:
        log.info("direct VPS file hosting is installed but disabled until PUBLIC_BASE_URL is set")
    log.info("keep-alive web server started on port %s", os.environ.get("PORT", C.PORT))

