def main():
    if not C.BOT_TOKEN:
        print("ERROR: no BOT_TOKEN found.")
        print("Ways to set it:")
        print("  1. Single-file edition: paste it into USER_BOT_TOKEN at the top of the file.")
        print("  2. Multi-file package: set BOT_TOKEN_FALLBACK in config.py, or a .env file.")
        print("  3. Set a real BOT_TOKEN environment variable (always wins).")
        return
    db.init_db()
    _ensure_template()          # GOJO x OMEGA rentable out of the box
    run_flask_keepalive()

    # optional speed-up: uvloop (Linux servers); silently skipped on Windows
    try:
        import uvloop
        uvloop.install()
        log.info("uvloop event loop active")
    except Exception:
        pass
    app = (Application.builder()
           .token(C.BOT_TOKEN)
           .concurrent_updates(True)   # handlers run in PARALLEL - no queue lag
           .post_init(post_init)
           .build())

    app.add_handler(CommandHandler("start", cmd_start), group=-1)
    app.add_handler(CommandHandler("help", cmd_help), group=-1)
    app.add_handler(CommandHandler("cancel", cmd_cancel), group=-1)
    app.add_handler(CommandHandler("balance", cmd_balance), group=-1)
    app.add_handler(CommandHandler("buy", cmd_buy), group=-1)
    app.add_handler(CommandHandler("paid", cmd_paid), group=-1)
    app.add_handler(CommandHandler("rent", cmd_rent), group=-1)
    app.add_handler(CommandHandler("host", cmd_host), group=-1)
    app.add_handler(CommandHandler("mybots", cmd_mybots), group=-1)
    app.add_handler(CommandHandler("myfiles", cmd_myfiles), group=-1)
    app.add_handler(CommandHandler("runtoken", cmd_runtoken), group=-1)
    app.add_handler(CommandHandler("panel", cmd_panel), group=-1)
    app.add_handler(CommandHandler("users", cmd_users), group=-1)
    app.add_handler(CommandHandler("deployments", cmd_deployments), group=-1)
    app.add_handler(CommandHandler("lock", cmd_lock), group=-1)
    app.add_handler(CommandHandler("unlock", cmd_unlock), group=-1)
    app.add_handler(CommandHandler("ownfile", cmd_ownfile), group=-1)
    app.add_handler(CommandHandler("settemplate", cmd_ownfile), group=-1)
    app.add_handler(CommandHandler("addcredits", cmd_addcredits), group=-1)
    app.add_handler(CommandHandler("rejectpayment", cmd_rejectpayment), group=-1)
    app.add_handler(CommandHandler("broadcast", cmd_broadcast), group=-1)
    app.add_handler(CommandHandler("pending", cmd_pending), group=-1)
    app.add_handler(CommandHandler("addadmin", cmd_addadmin), group=-1)
    app.add_handler(CommandHandler("removeadmin", cmd_removeadmin), group=-1)
    app.add_handler(CommandHandler("addcoowner", cmd_addcoowner), group=-1)
    app.add_handler(CommandHandler("removecoowner", cmd_removecoowner), group=-1)
    app.add_handler(CommandHandler("staff", cmd_staff), group=-1)

    # guard must run before everything else
    from telegram.ext import TypeHandler
    app.add_handler(TypeHandler(Update, guard), group=-2)

    app.add_handler(CallbackQueryHandler(cb_router), group=0)
    app.add_handler(MessageHandler(filters.Document.ALL & ~filters.COMMAND, on_upload), group=0)
    app.add_handler(MessageHandler(filters.PHOTO & ~filters.COMMAND, photo_router), group=0)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, text_router), group=0)

    # billing every 30 min (charges only when 24h passed)
    if app.job_queue:
        app.job_queue.run_repeating(billing_job, interval=1800, first=60)
    else:
        log.warning("python-telegram-bot[job-queue] not installed — billing disabled!")

    log.info("platform starting")
    try:
        app.run_polling(allowed_updates=["message", "callback_query"])
    except Exception as e:
        print()
        print("=" * 64)
        print("BOT FAILED TO START:", type(e).__name__)
        print(str(e)[:300])
        if "token" in str(e).lower() or "unauthor" in str(e).lower():
            print()
            print("Telegram rejected your BOT_TOKEN. Check that you pasted the")
            print("FULL token from @BotFather (it looks like")
            print("123456789:AAE...long-string...) with no extra spaces or quotes.")
        print("=" * 64)


